import fs from 'node:fs';
const base = 'http://localhost:18080/api/asistente/preguntar';
const qs = JSON.parse(fs.readFileSync(new URL('../preguntas_ejemplo.json', import.meta.url), 'utf8'));
const out = new URL('./resultados.jsonl', import.meta.url);
fs.writeFileSync(out, '');
async function una(q, modo, ronda) {
  const t0 = performance.now();
  let status = 0, cid = null, tokens = null;
  try {
    const r = await fetch(base, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ pregunta: q.pregunta, usuario: { rol: q.usuario.rol, id: q.usuario.id } }),
      signal: AbortSignal.timeout(300000),
    });
    status = r.status; cid = r.headers.get('x-correlation-id');
    const j = await r.json().catch(() => ({}));
    tokens = j.tokens ?? null;
  } catch (e) { status = -1; }
  const ms = Math.round(performance.now() - t0);
  fs.appendFileSync(out, JSON.stringify({ modo, ronda, id: q.id, status, cid, ms, tokens }) + '\n');
  console.log(modo, ronda, q.id, status, ms);
}
const modo = process.argv[2];
if (modo === 'sec') {
  for (const q of qs) for (let i = 1; i <= 5; i++) await una(q, 'sec', i);
} else {
  for (let t = 1; t <= 3; t++) {
    const lote = Array.from({ length: 8 }, (_, k) => qs[(k * 3 + t * 5) % qs.length]);
    await Promise.all(lote.map((q) => una(q, 'conc', t)));
  }
}

