import fs from 'node:fs';
const res = fs.readFileSync(new URL('./resultados.jsonl', import.meta.url), 'utf8').trim().split('\n').map(JSON.parse);
const tr = {};
for (const l of fs.readFileSync(new URL('./llm-trace.tsv', import.meta.url), 'utf8').trim().split('\n')) {
  const [id, tipo, ms, extra] = l.split('\t');
  tr[id] ??= { llm: [], fase: null, reint: false };
  if (tipo === 'LLM') tr[id].llm.push(+ms);
  else { tr[id].fase = +ms; tr[id].reint = extra.includes('reintento=True'); }
}
const pct = (a, p) => { const s = [...a].sort((x, y) => x - y); return s[Math.min(s.length - 1, Math.ceil(p * s.length) - 1)]; };
const rows = [];
for (const modo of ['sec', 'conc']) {
  const ids = [...new Set(res.filter((r) => r.modo === modo).map((r) => r.id))].sort((a, b) => a - b);
  for (const id of [...ids, 'TODAS']) {
    const rs = res.filter((r) => r.modo === modo && (id === 'TODAS' || r.id === id));
    const tot = rs.map((r) => r.ms);
    const fa = rs.map((r) => tr[r.cid]?.fase).filter((x) => x != null);
    const calls = rs.map((r) => tr[r.cid]?.llm.length ?? 0);
    const reint = rs.filter((r) => tr[r.cid]?.reint).length;
    rows.push([modo, id, rs.length, pct(tot, .5), pct(tot, .95), Math.max(...tot),
      fa.length ? pct(fa, .5) : '-', fa.length ? pct(fa, .95) : '-', fa.length ? Math.max(...fa) : '-',
      calls.reduce((a, b) => a + b, 0), reint, rs.filter((r) => r.status === 503).length,
      rs.filter((r) => r.ms > 20000).length, rs.filter((r) => r.ms > 60000).length].join('\t'));
  }
}
console.log('modo\tpregunta\tn\ttot_p50\ttot_p95\ttot_max\tfase_p50\tfase_p95\tfase_max\tllamadasLLM\treintentos\t503\t>20s\t>60s');
console.log(rows.join('\n'));

